  values ('deal:aston-villa-football-club:marc-zahr-co-president-blue-owl-capital:2025-10-21', '2025-10-21', '21 October 2025', 'minority_investment', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'Marc Zahr (co-president, Blue Owl Capital)', 'individual', (select id from public.companies where lower(name) = lower('Marc Zahr (co-president, Blue Owl Capital)') limit 1), (select id from public.sports_investors where lower(name) = lower('Marc Zahr (co-president, Blue Owl Capital)') limit 1), 'V Sports', 10, null, null, null, null, 'Marc Zahr buys 10% of Aston Villa Women and joins its board', 'V Sports announced the sale of a 10% stake in Aston Villa Women to Marc Zahr, co-president of Blue Owl Capital, who was to join the women''s club''s board of directors.', 'Aston Villa FC (official)', 'https://www.avfc.co.uk/news/2025/october/21/investment-made-into-aston-villa-women/', 'web_research')
